const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sistanBaluchestan = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Sistan and Baluchestan'));

  const startDate = '2020-01-08';
  const endDate = '2020-01-15';

  // 2. Data Acquisition - GPM IMERG for precipitation
  const precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(sistanBaluchestan);

  const precipSize = precipCol.size().getInfo();
  console.log(`GPM Images: ${precipSize}`);

  if (precipSize === 0) {
    console.log("No precipitation data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = precipCol.sum();

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sistanBaluchestan,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid precipitation pixels.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sistanBaluchestan,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  console.log(`Total precipitation (mm): ${meanPrecip ? meanPrecip.toFixed(2) : 'null'}`);

  // 5. Validation & Final Answer
  if (meanPrecip === null || meanPrecip === undefined || isNaN(meanPrecip)) {
    console.log("<answer>C3</answer>");
  } else {
    const inches = meanPrecip / 25.4; // Convert mm to inches
    console.log(`Total precipitation (inches): ${inches.toFixed(2)}`);

    if (inches > 3) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
